package cn.mint.tv;
import org.junit.*;import static org.junit.Assert.*;import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;import org.json.*;
public class EpgParserTest {
 final long now=EpgParser.time("20261123123000 +0800");
 JSONObject parse(String body,Map<String,String> ids,Set<String> names)throws Exception{return EpgParser.parse(new ByteArrayInputStream(("<tv>"+body+"</tv>").getBytes(StandardCharsets.UTF_8)),ids,names,now);}
 String program(String id,String start,String stop,String title){return "<programme channel='"+id+"' start='20261123"+start+" +0800' stop='20261123"+stop+" +0800'><title>"+title+"</title></programme>";}
 @Test public void picksCurrentAndNearestNextRegardlessOfOrder()throws Exception{Map<String,String> ids=Collections.singletonMap("id","cctv1");JSONObject out=parse(program("id","150000","160000","later")+program("id","130000","140000","next")+program("id","120000","130000","now")+program("unknown","120000","130000","other"),ids,Collections.emptySet());assertEquals(1,out.length());assertEquals("now",out.getJSONObject("cctv1").getJSONObject("now").getString("title"));assertEquals("next",out.getJSONObject("cctv1").getJSONObject("next").getString("title"));}
 @Test public void matchesDisplayNameWhenTvgIdAbsent()throws Exception{JSONObject out=parse("<channel id='local'><display-name>CCTV-1</display-name></channel>"+program("local","120000","130000","午间节目"),Collections.emptyMap(),Collections.singleton(Playlist.key("CCTV-1")));assertEquals("午间节目",out.getJSONObject(Playlist.key("CCTV-1")).getJSONObject("now").getString("title"));}
 @Test public void explicitTvgIdWinsOverDisplayName()throws Exception{JSONObject out=parse("<channel id='id'><display-name>B</display-name></channel>"+program("id","120000","130000","show"),Collections.singletonMap("id","a"),Collections.singleton("b"));assertTrue(out.has("a"));assertFalse(out.has("b"));}
 @Test public void ignoresExpiredAndInvalidTimes()throws Exception{assertEquals(0,parse(program("id","100000","110000","expired")+program("id","140000","130000","invalid"),Collections.singletonMap("id","a"),Collections.emptySet()).length());assertEquals(-1,EpgParser.time("20260230120000 +0800"));}
 @Test public void honorsTimezoneOffset() {assertEquals(EpgParser.time("20261123043000 +0000"),now);}
 @Test public void externalDtdDoesNotRequireNetwork()throws Exception{String xml="<!DOCTYPE tv SYSTEM 'https://invalid.example/xmltv.dtd'><tv>"+program("id","120000","130000","show")+"</tv>";JSONObject data=EpgParser.parse(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)),Collections.singletonMap("id","a"),Collections.emptySet(),now);assertTrue(data.has("a"));}
 @Test public void neverExpandsExternalEntity()throws Exception{File secret=File.createTempFile("mint-epg",".txt");try{try(FileOutputStream out=new FileOutputStream(secret)){out.write("PRIVATE_SENTINEL".getBytes(StandardCharsets.UTF_8));}String xml="<!DOCTYPE tv [<!ENTITY x SYSTEM '"+secret.toURI()+"'>]><tv>"+program("id","120000","130000","&x;")+"</tv>";try{JSONObject data=EpgParser.parse(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)),Collections.singletonMap("id","a"),Collections.emptySet(),now);assertFalse(data.toString().contains("PRIVATE_SENTINEL"));}catch(org.xml.sax.SAXException expected){}}finally{secret.delete();}}
 @Test public void rejectsInternalEntityExpansion()throws Exception{String xml="<!DOCTYPE tv [<!ENTITY x 'EXPANDED'>]><tv>"+program("id","120000","130000","&x;")+"</tv>";try{EpgParser.parse(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)),Collections.singletonMap("id","a"),Collections.emptySet(),now);fail();}catch(org.xml.sax.SAXException expected){}}
 @Test public void refusesOversizeStream()throws Exception{try{new EpgParser.Limited(new ByteArrayInputStream(new byte[20]),10).read(new byte[20],0,20);fail();}catch(IOException expected){}}
 @Test public void retainsAtMostTwoProgramsPerChannel()throws Exception{StringBuilder xml=new StringBuilder();for(int i=0;i<1000;i++)xml.append(program("id","120000","130000","show"));JSONObject data=parse(xml.toString(),Collections.singletonMap("id","a"),Collections.emptySet());assertEquals(1,data.getJSONObject("a").length());}
 @Test public void playlistPreservesTvgIdAcrossMerge(){List<Playlist.Channel> a=Playlist.parse("#EXTM3U\n#EXTINF:-1 tvg-id=\"station.1\" group-title=\"央视\",CCTV-1\nhttps://a/live");assertEquals("station.1",a.get(0).tvgId);assertEquals("station.1",Playlist.merge(a,Playlist.parse("CCTV-1,https://b/live")).get(0).tvgId);}
}
